let currentLocale = "en";
export const getLocale = () => currentLocale;
export function setLocale(value) { currentLocale = value === "zh" ? "zh" : "en"; }
export function tr(zh) { return currentLocale === "en" ? EN[zh] ?? zh : zh; }
export function fmt(zh, values = {}) {
  return tr(zh).replace(/\{([a-zA-Z0-9_]+)\}/g, (_, key) => String(values[key] ?? ""));
}
